SELECT id, object_id, record_id, source_id, anchor_entry_id, space_id, entry_id,
       origin, auto_name, creator, create_time, updater, update_time, deleted
FROM public.nocode_record_folder_binding
WHERE object_id = #{objectId}
AND record_id = #{recordId}
AND source_id = #{sourceId}
AND anchor_entry_id = #{anchorEntryId}
AND deleted = 0

SELECT record_id
FROM public.nocode_record_folder_binding
WHERE object_id = #{objectId}
AND source_id = #{sourceId}
AND anchor_entry_id = #{anchorEntryId}
AND deleted = 0
AND record_id IN
#{recordId}
